import json
import os
import pathlib
import re
import sys

GENERATED_ROOT = pathlib.Path('/root/scripts').resolve()
TERMS = re.compile(r'ssh|student|password|passwd|credential|authorized[_ -]?keys?|private[ _-]?key|login|access|authentication|identity', re.I)


def is_under(path, root):
    try:
        path.resolve().relative_to(root)
        return True
    except (OSError, ValueError):
        return False


def emit(obj):
    print(json.dumps(obj, ensure_ascii=False, sort_keys=True))


cwd = pathlib.Path.cwd().resolve()
report = {
    'purpose': 'Review accessible task-workspace materials and relevant repository history for explicit student SSH access evidence; generated scripts are excluded.',
    'workspace': str(cwd),
    'excluded_provenance_path': str(GENERATED_ROOT),
    'files_examined': [],
    'matching_file_lines': [],
    'access_errors': [],
    'repositories': [],
    'coverage_notes': [],
}

# Examine the workspace tree, skipping VCS internals and the provenance-identified
# generated action directory. Include hidden task files and repository metadata files.
if cwd == pathlib.Path('/'):
    report['coverage_notes'].append('Workspace is filesystem root; recursive file review was not attempted to avoid treating the entire machine as task-supplied material.')
else:
    for dirpath, dirnames, filenames in os.walk(str(cwd), followlinks=False):
        current = pathlib.Path(dirpath)
        kept = []
        for name in dirnames:
            candidate = current / name
            if name == '.git':
                continue
            if is_under(candidate, GENERATED_ROOT):
                report['coverage_notes'].append('Excluded provenance-identified generated directory: ' + str(candidate))
                continue
            kept.append(name)
        dirnames[:] = kept
        for name in filenames:
            path = current / name
            if is_under(path, GENERATED_ROOT):
                continue
            try:
                with path.open('rb') as f:
                    first = f.read(4096)
                    if b'\x00' in first:
                        continue
                    f.seek(0)
                    data = f.read()
                text = data.decode('utf-8')
            except (OSError, UnicodeError) as exc:
                report['access_errors'].append({'path': str(path), 'error': repr(exc)})
                continue
            report['files_examined'].append(str(path))
            for line_no, line in enumerate(text.splitlines(), 1):
                if TERMS.search(line):
                    report['matching_file_lines'].append({'path': str(path), 'line': line_no, 'text': line[:2000]})

# Locate repositories rooted at the workspace or nested within it, including a
# repository enclosing the current directory. .git files are supported (worktrees).
repo_roots = set()
for ancestor in (cwd, *cwd.parents):
    marker = ancestor / '.git'
    if marker.is_dir() or marker.is_file():
        repo_roots.add(ancestor)
        break
if cwd != pathlib.Path('/'):
    for dirpath, dirnames, filenames in os.walk(str(cwd), followlinks=False):
        current = pathlib.Path(dirpath)
        if is_under(current, GENERATED_ROOT):
            dirnames[:] = []
            continue
        if '.git' in dirnames or '.git' in filenames:
            repo_roots.add(current.resolve())
            dirnames[:] = [d for d in dirnames if d != '.git']
        dirnames[:] = [d for d in dirnames if not is_under(current / d, GENERATED_ROOT)]

try:
    from framework_evidence import run_tool
except Exception as exc:
    run_tool = None
    report['coverage_notes'].append('framework_evidence import failed; Git history could not be reviewed through the supplied evidence helper: ' + repr(exc))

for repo in sorted(repo_roots, key=str):
    repo_record = {'path': str(repo), 'commands': []}
    report['repositories'].append(repo_record)
    if run_tool is None:
        continue
    commands = [
        ['git', '-C', str(repo), 'log', '--all', '--format=%H%x09%ad%x09%s', '--date=iso-strict'],
        ['git', '-C', str(repo), 'log', '--all', '--pickaxe-regex', '-G', '(ssh|student|password|passwd|credential|authorized[_ -]?keys?|private[ _-]?key|login|access|authentication)', '--format=commit %H %ad %s', '--date=iso-strict', '-p', '--'],
    ]
    for argv in commands:
        entry = {'argv': argv}
        try:
            envelope = run_tool(argv)
            entry['evidence_envelope'] = envelope
        except Exception as exc:
            entry['helper_error'] = repr(exc)
        repo_record['commands'].append(entry)

if not repo_roots:
    report['coverage_notes'].append('No Git repository marker was found in the workspace or its enclosing directories.')
if not report['files_examined']:
    report['coverage_notes'].append('No readable UTF-8, non-binary files were examined in the workspace tree.')
emit(report)"},

