import json
import os
import re
import subprocess
from pathlib import Path

GENERATED_ROOT = Path('/root/scripts').resolve()
KEYWORDS = re.compile(r'(?i)(ssh|student|credential|password|passphrase|private.?key|authorized.?keys|login|access)')
SECRET = re.compile(r'(?i)(password|passphrase|token|secret|private.?key)\s*[:=]\s*\S+')
PRUNE = {'.git', '.cache', '.local', 'node_modules', '__pycache__', 'proc', 'sys', 'dev'}

report = {
    'purpose': 'Review accessible task-supplied repository files and Git history for explicit SSH access instructions or credentials for student.',
    'generated_artifacts_excluded': [str(GENERATED_ROOT)],
    'repository_discovery': [],
    'repositories': [],
    'coverage_limitations': [],
    'access_matches': []
}

def is_generated(path):
    try:
        path.resolve().relative_to(GENERATED_ROOT)
        return True
    except (ValueError, OSError):
        return False

def candidates():
    found = set()
    cwd = Path.cwd().resolve()
    bases = [cwd, Path('/workspace'), Path('/root')]
    for base in list(bases):
        if base.exists() and base.is_dir() and not is_generated(base):
            found.add(base)
            try:
                for child in base.iterdir():
                    if child.is_dir() and not is_generated(child):
                        found.add(child.resolve())
            except OSError as exc:
                report['coverage_limitations'].append({'path': str(base), 'error': str(exc)})
    for parent in [cwd, *cwd.parents]:
        if not is_generated(parent):
            found.add(parent)
    return sorted(found, key=lambda p: (len(p.parts), str(p)))

# Discover repositories in the current location and the likely task workspace roots.
repo_roots = set()
for path in candidates():
    if is_generated(path):
        continue
    try:
        result = subprocess.run(
            ['git', '-C', str(path), 'rev-parse', '--show-toplevel'],
            capture_output=True, text=True, timeout=15
        )
        report['repository_discovery'].append({
            'path': str(path), 'exit_code': result.returncode,
            'stdout': result.stdout.strip(), 'stderr': result.stderr.strip()
        })
        if result.returncode == 0 and result.stdout.strip():
            root = Path(result.stdout.strip()).resolve()
            if not is_generated(root):
                repo_roots.add(root)
    except (OSError, subprocess.TimeoutExpired) as exc:
        report['coverage_limitations'].append({'path': str(path), 'operation': 'git repository discovery', 'error': str(exc)})

# Also locate nested repositories under the current working directory and /workspace.
for base in [Path.cwd().resolve(), Path('/workspace')]:
    if not base.exists() or not base.is_dir() or is_generated(base):
        continue
    for current, dirs, files in os.walk(base, onerror=lambda exc: report['coverage_limitations'].append({'path': getattr(exc, 'filename', str(base)), 'error': str(exc)})):
        current_path = Path(current).resolve()
        dirs[:] = [d for d in dirs if d not in PRUNE and not is_generated(current_path / d)]
        if '.git' in dirs or (current_path / '.git').exists():
            if not is_generated(current_path):
                repo_roots.add(current_path)
            dirs[:] = [d for d in dirs if d != '.git']

try:
    from framework_evidence import run_tool
except Exception as exc:
    run_tool = None
    report['coverage_limitations'].append({'operation': 'load framework evidence helper', 'error': str(exc)})

for root in sorted(repo_roots, key=str):
    entry = {'root': str(root), 'provenance': 'accessible filesystem repository; task-supplied status is not independently guaranteed', 'files_examined': [], 'git_history': [], 'errors': []}
    report['repositories'].append(entry)
    if run_tool is not None:
        for label, argv in [
            ('tracked and non-ignored file inventory', ['git', '-C', str(root), 'ls-files', '--cached', '--others', '--exclude-standard', '-z']),
            ('history changes matching access-related terms', ['git', '-C', str(root), 'log', '--all', '--format=%H%x09%cs%x09%s', '-G', r'(?i)(ssh|student|password|credential|authorized.?keys|private.?key|login)', '--'])
        ]:
            try:
                envelope = run_tool(argv)
                entry['git_history'].append({'purpose': label, 'envelope': envelope})
                if label == 'tracked and non-ignored file inventory':
                    out = envelope.get('stdout', '') if isinstance(envelope, dict) else ''
                    if isinstance(out, str):
                        file_names = [name for name in out.split('\0') if name]
                    else:
                        file_names = []
                elif label == 'history changes matching access-related terms':
                    pass
            except Exception as exc:
                entry['errors'].append({'operation': label, 'error': str(exc)})
                file_names = []
    else:
        file_names = []
        entry['errors'].append({'operation': 'Git inventory/history', 'error': 'framework_evidence.run_tool unavailable'})

    # Read accessible repository files by path for relevant lines. Never read generated scripts.
    if not file_names:
        try:
            proc = subprocess.run(['git', '-C', str(root), 'ls-files', '--cached', '--others', '--exclude-standard', '-z'], capture_output=True, timeout=30)
            if proc.returncode == 0:
                file_names = [x.decode('utf-8', 'surrogateescape') for x in proc.stdout.split(b'\0') if x]
            else:
                entry['errors'].append({'operation': 'git file inventory fallback', 'exit_code': proc.returncode, 'stderr': proc.stderr.decode('utf-8', 'replace')})
        except (OSError, subprocess.TimeoutExpired) as exc:
            entry['errors'].append({'operation': 'git file inventory fallback', 'error': str(exc)})
    for name in file_names:
        path = (root / name).resolve()
        if is_generated(path):
            continue
        try:
            if not path.is_file():
                continue
            data = path.read_bytes()
            if b'\0' in data:
                continue
            text = data.decode('utf-8', 'replace')
            entry['files_examined'].append(name)
            for number, line in enumerate(text.splitlines(), 1):
                if KEYWORDS.search(line):
                    cleaned = SECRET.sub(lambda m: m.group(1) + '=[REDACTED]', line)
                    report['access_matches'].append({
                        'source': str(path), 'repository': str(root), 'line': number,
                        'match': cleaned[:2000], 'provenance': 'current accessible repository file'
                    })
        except OSError as exc:
            entry['errors'].append({'path': str(path), 'error': str(exc)})

report['coverage_summary'] = {
    'repositories_found': len(report['repositories']),
    'repository_files_examined': sum(len(r['files_examined']) for r in report['repositories']),
    'relevant_current_file_lines': len(report['access_matches']),
    'history_search': 'Git log -G search was requested for all reachable refs in each discovered repository; inspect returned envelopes and any command status.',
    'limitations': 'Discovery covered the current working directory and its ancestors, immediate child directories of /workspace and /root, and nested repositories under the current directory and /workspace. Other filesystem locations were not searched.'
}
print(json.dumps(report, ensure_ascii=False, indent=2))

