import json
import os
import re
import subprocess

GENERATED = os.path.realpath('/root/scripts')
TEXT_EXTENSIONS = {
    '.md', '.markdown', '.txt', '.rst', '.json', '.yaml', '.yml', '.toml',
    '.ini', '.cfg', '.conf', '.sh', '.py', '.xml', '.html', '.csv', '.log'
}
NAME_HINTS = ('ssh', 'student', 'credential', 'password', 'passwd', 'authorized', 'key', 'access', 'task', 'readme', 'instruction')
TERMS = re.compile(r'(student|ssh|password|passwd|credential|private\s*key|authorized_keys|login|username|identityfile)', re.I)
KEY_MARKER = re.compile(r'-----BEGIN (?:OPENSSH |RSA |EC |DSA )?PRIVATE KEY-----')

roots = []
for candidate in [os.getcwd(), '/workspace', '/root', '/tmp', '/home', '/opt', '/mnt', '/media', '/srv', '/var/tmp']:
    path = os.path.realpath(candidate)
    if os.path.isdir(path) and path not in roots and not (path == GENERATED or path.startswith(GENERATED + os.sep)):
        roots.append(path)

examined_files = []
relevant_hits = []
key_file_candidates = []
repositories = set()
access_errors = []
visited_directories = 0


def excluded(path):
    real = os.path.realpath(path)
    return real == GENERATED or real.startswith(GENERATED + os.sep)

for root in roots:
    for current, dirs, files in os.walk(root, topdown=True, followlinks=False, onerror=lambda e: access_errors.append({'path': getattr(e, 'filename', None), 'error': str(e)})):
        if excluded(current):
            dirs[:] = []
            continue
        visited_directories += 1
        if '.git' in dirs:
            repositories.add(os.path.realpath(current))
            dirs.remove('.git')
        kept = []
        for name in dirs:
            path = os.path.join(current, name)
            if not excluded(path):
                kept.append(name)
        dirs[:] = kept
        for name in files:
            path = os.path.join(current, name)
            if excluded(path):
                continue
            lower_name = name.lower()
            is_candidate = os.path.splitext(lower_name)[1] in TEXT_EXTENSIONS or any(hint in lower_name for hint in NAME_HINTS)
            if not is_candidate:
                continue
            try:
                if not os.path.isfile(path):
                    continue
                examined_files.append(path)
                with open(path, 'rb') as f:
                    raw = f.read()
                if KEY_MARKER.search(raw.decode('ascii', errors='ignore')):
                    key_file_candidates.append({'path': path, 'observation': 'private-key marker present; key material omitted'})
                    continue
                text = raw.decode('utf-8', errors='strict')
                matching = []
                for number, line in enumerate(text.splitlines(), 1):
                    if TERMS.search(line):
                        matching.append({'line': number, 'text': line[:1000]})
                if matching:
                    relevant_hits.append({'path': path, 'provenance': 'accessible filesystem path; task-supplied status not independently verified', 'matches': matching})
            except (OSError, UnicodeError) as exc:
