history_results = []
try:
    from framework_evidence import run_tool
    for repo in sorted(repositories):
        argv = ['git', '-C', repo, 'log', '--all', '--format=%H%x09%cs%x09%s', '-G', '(student|ssh|password|passwd|credential|private.key|authorized_keys|login|username)', '--', '.']
        try:
            envelope = run_tool(argv)
            history_results.append({'repository': repo, 'provenance': 'repository discovered at accessible filesystem path; task-supplied status not independently verified', 'argv': argv, 'result': envelope})
        except Exception as exc:
            history_results.append({'repository': repo, 'argv': argv, 'error': str(exc)})
except Exception as exc:
    history_results.append({'error': 'framework_evidence import or use failed', 'detail': str(exc)})

result = {
    'purpose': 'Review accessible candidate task materials for explicit student SSH access instructions or credentials; generated scripts excluded.',
    'roots_examined': roots,
    'generated_path_excluded': GENERATED,
    'coverage': {
        'directories_visited': visited_directories,
        'candidate_files_examined': len(examined_files),
        'examined_paths': examined_files,
        'repositories_discovered': sorted(repositories),
        'history_review_method': 'git log across reachable refs with an access-related diff regex; returned evidence envelopes retained'
    },
    'relevant_text_matches': relevant_hits,
    'private_key_file_observations': key_file_candidates,
    'repository_history_results': history_results,
    'access_or_provenance_limitations': access_errors,
    'interpretation': 'Only listed sources and returned history results were examined. Filesystem location alone does not prove task-supplied provenance; no-match results do not establish absence in unexamined sources.'
}
print(json.dumps(result, ensure_ascii=False))

