import json
import os
import re
import sys
from pathlib import Path

try:
    from framework_evidence import run_tool
except Exception as exc:
    print(json.dumps({"status": "helper_unavailable", "error": repr(exc), "coverage": "No repository commands were run."}, ensure_ascii=False))
    raise SystemExit(0)

EXCLUDED = Path("/root/scripts").resolve()
MAX_DEPTH = 8
PATTERN = re.compile(r"ssh|student|credential|password|passwd|authorized[_ -]?keys|private[ _-]?key|login|access", re.I)


def excluded(path):
    try:
        Path(path).resolve().relative_to(EXCLUDED)
        return True
    except (ValueError, OSError):
        return False


def run(argv):
    try:
        return run_tool(argv)
    except Exception as exc:
        return {"command": argv, "helper_error": repr(exc)}


def find_stdout(value):
    if isinstance(value, dict):
        if isinstance(value.get("stdout"), str):
            return value["stdout"]
        runs = value.get("tool_runs")
        if isinstance(runs, list):
            for item in runs:
                found = find_stdout(item)
                if found is not None:
                    return found
    return None

cwd = Path.cwd().resolve()
roots = [cwd]
for candidate in (Path("/workspace"), Path("/workspaces"), Path("/app"), Path("/mnt/data"), Path("/root")):
    candidate = candidate.resolve()
    if candidate.is_dir() and candidate not in roots:
        roots.append(candidate)

repos = set()
walk_errors = []
root_coverage = []
for base in roots:
    if excluded(base):
        root_coverage.append({"root": str(base), "status": "excluded_generated_scripts"})
        continue
    # Include repository ancestors of the working directory, if any.
    if base == cwd:
        for ancestor in (cwd, *cwd.parents):
            if excluded(ancestor):
                continue
            marker = ancestor / ".git"
            if marker.exists():
                repos.add(str(ancestor.resolve()))
    visited = 0
    for current, dirs, files in os.walk(base, topdown=True, onerror=lambda e, b=str(base): walk_errors.append({"root": b, "error": str(e)})):
        current_path = Path(current).resolve()
        try:
            depth = len(current_path.relative_to(base).parts)
        except ValueError:
            dirs[:] = []
            continue
        if excluded(current_path) or depth >= MAX_DEPTH:
            dirs[:] = []
            continue
        dirs[:] = [d for d in dirs if d != ".git" and not excluded(current_path / d)]
        visited += 1
        if ".git" in files or (current_path / ".git").is_dir():
            repos.add(str(current_path))
    root_coverage.append({"root": str(base), "status": "walked", "maximum_relative_depth": MAX_DEPTH, "directories_visited": visited})

results = []
for repo_name in sorted(repos):
    repo = Path(repo_name)
    if excluded(repo):
        continue
    item = {"repository": str(repo), "provenance": "Git repository; tracked files are identified by Git, but repository location alone does not establish task-supplied provenance."}
    item["branch_metadata"] = run(["git", "-C", str(repo), "branch", "--all", "--no-color"])
    item["status_metadata"] = run(["git", "-C", str(repo), "status", "--short", "--branch", "--untracked-files=normal"])
    listing = run(["git", "-C", str(repo), "ls-files", "-z"])
    item["tracked_file_listing_evidence"] = listing
    stdout = find_stdout(listing)
    paths = stdout.split("\0") if stdout else []
    paths = [p for p in paths if p and not excluded(repo / p)]
    examined = 0
    read_errors = []
    matches = []
    for relative in paths:
        path = repo / relative
        try:
            data = path.read_bytes()
        except OSError as exc:
            read_errors.append({"path": relative, "error": str(exc)})
            continue
        try:
            text = data.decode("utf-8")
        except UnicodeDecodeError as exc:
            read_errors.append({"path": relative, "error": "not UTF-8 text; " + str(exc)})
            continue
        examined += 1
        for line_number, line in enumerate(text.splitlines(), 1):
            if PATTERN.search(line):
                matches.append({"path": relative, "line": line_number, "text": line, "provenance": "current Git-tracked working-tree file"})
    item["tracked_files"] = {"listed": len(paths), "UTF8_text_examined": examined, "read_or_decode_errors": read_errors, "relevant_pattern_matches": matches, "coverage_note": "All listed, accessible UTF-8 Git-tracked working-tree files were checked line-by-line with the stated relevance pattern. Binary/non-UTF-8 and inaccessible files are listed as limitations; untracked files are not included."}
    history = run(["git", "-C", str(repo), "log", "--all", "--full-history", "--regexp-ignore-case", "-G", "ssh|student|credential|password|passwd|authorized[_ -]?keys|private[ _-]?key|login|access", "--format=commit %H %aI %s", "-p", "--"])
    item["history_search"] = {"search_pattern": PATTERN.pattern, "branches": "all refs visible to this repository", "evidence": history, "coverage_note": "Git patches matching the pattern are returned for history reachable from visible refs; this does not cover unreachable objects, omitted refs, or sources outside this repository."}
    results.append(item)

print(json.dumps({"purpose": "Review task-related access instructions and credentials in accessible workspace repository sources and history; no SSH authentication was attempted.", "working_directory": str(cwd), "excluded_generated_path": str(EXCLUDED), "workspace_roots": root_coverage, "repository_count": len(results), "repositories": results, "filesystem_walk_errors": walk_errors, "search_coverage": "Repository discovery was limited to the working directory and listed common workspace roots, to relative depth 8. Git-tracked current files and matching patches on visible refs were examined. Repository location does not prove task-supplied provenance; untracked files, inaccessible paths, unexamined roots, non-UTF-8 current files, and unreachable Git history remain outside the findings.", "interpretation": "A reported match is evidence in the cited source only; absence of matches is not evidence that unexamined sources contain no credentials or instructions."}, ensure_ascii=False))

