import hashlib
import json
import os
import re
import sys

EXCLUDED_EXACT = {os.path.realpath('/root/scripts')}
PRUNE_NAMES = {'.git', '.cache', '__pycache__', 'node_modules'}
# Lines are reported only when they explicitly appear relevant to SSH access,
# credentials, or login instructions; credentials are not guessed.
RELEVANT = re.compile(
    r'(?i)(ssh|authorized_keys|private.?key|public.?key|credential|password|'
    r'passphrase|login|access instruction|student\s+user|user(name)?\s*[:=])'
)


def under(path, parent):
    try:
        return os.path.commonpath([path, parent]) == parent
    except ValueError:
        return False


def main():
    roots = []
    for raw in ('/root', '/home', '/tmp'):
        path = os.path.realpath(raw)
        if os.path.isdir(path) and path not in roots:
            roots.append(path)

    files = []
    errors = []
    excluded = []
    seen = set()

    for root in roots:
        for current, dirs, names in os.walk(root, topdown=True, followlinks=False):
            real_current = os.path.realpath(current)
            if any(under(real_current, path) for path in EXCLUDED_EXACT):
                dirs[:] = []
                excluded.append({'path': current, 'reason': 'known generated artifacts: /root/scripts'})
                continue
            kept = []
            for dirname in dirs:
                child = os.path.realpath(os.path.join(current, dirname))
                if dirname in PRUNE_NAMES:
                    excluded.append({'path': os.path.join(current, dirname), 'reason': 'generated/cache or repository metadata directory not reviewed'})
                elif any(under(child, path) for path in EXCLUDED_EXACT):
                    excluded.append({'path': os.path.join(current, dirname), 'reason': 'known generated artifacts: /root/scripts'})
                else:
                    kept.append(dirname)
            dirs[:] = kept

            for name in names:
                path = os.path.join(current, name)
                real_path = os.path.realpath(path)
                if any(under(real_path, item) for item in EXCLUDED_EXACT):
                    excluded.append({'path': path, 'reason': 'known generated artifacts: /root/scripts'})
                    continue
                if real_path in seen or not os.path.isfile(path):
                    continue
                seen.add(real_path)
                try:
                    with open(path, 'rb') as stream:
                        raw_data = stream.read()
                    text = raw_data.decode('utf-8')
                except UnicodeDecodeError:
                    continue
                except OSError as exc:
                    errors.append({'path': path, 'error': str(exc), 'stage': 'read'})
                    continue

                matches = []
                for number, line in enumerate(text.splitlines(), 1):
                    if RELEVANT.search(line):
                        matches.append({'line': number, 'text': line[:2000]})
                files.append({
                    'path': path,
                    'sha256': hashlib.sha256(raw_data).hexdigest(),
                    'bytes': len(raw_data),
                    'reviewed_as_utf8_text': True,
                    'provenance': 'not established as task-provided; filesystem path and contents alone do not establish origin',
                    'previously_reviewed_status': 'unknown; accessible prior inspection records did not identify paths in the supplied evidence',
                    'explicit_access_relevant_lines': matches,
                })

    print(json.dumps({
        'purpose': 'Inventory and review accessible user-level text sources for explicit authorized student SSH access material.',
        'search_roots': roots,
        'sources_reviewed': files,
        'access_errors': errors,
        'excluded_paths': excluded,
        'coverage': {
            'previous_inspection_records': 'The supplied record is partial and does not identify all reviewed source paths; distinct-unreviewed status cannot be established for discovered files.',
            'provenance': 'Only /root/scripts was identified as generated and excluded. Other discovered files are not asserted to be task-provided.',
            'scope': 'Readable UTF-8 files beneath /root, /home, and /tmp; undecodable files are not content-reviewed. Common repository metadata and cache directories are excluded.',
            'conclusion_limit': 'No finding in this inventory would establish absence of access material outside reviewed files or establish task provenance for files of unknown origin.'
        }
    }, ensure_ascii=False))


if __name__ == '__main__':
    main()

