import json
import os
import re
import stat
from pathlib import Path

REVIEWED_ROOTS = (Path('/root'), Path('/home'), Path('/tmp'))
GENERATED_ROOT = Path('/root/scripts')
SOURCE_KEY = re.compile(r'(?:task|autopenbench).*(?:input|source|material).*(?:path|dir|file)?|(?:input|source|material).*(?:task).*(?:path|dir|file)?', re.I)
PATH_FIELD = re.compile(r'(?:task|input|source|material).*(?:path|dir|file)|(?:path|dir|file).*(?:task|input|source|material)', re.I)
RELEVANT = re.compile(r'\b(ssh|student|credential|password|passphrase|private[ _-]?key|public[ _-]?key|authorized|login|access|user(name)?|host(name)?|port)\b', re.I)


def outside_reviewed_roots(path):
    resolved = path.resolve(strict=False)
    for root in REVIEWED_ROOTS:
        try:
            resolved.relative_to(root.resolve(strict=False))
            return False
        except ValueError:
            pass
    try:
        resolved.relative_to(GENERATED_ROOT.resolve(strict=False))
        return False
    except ValueError:
        return True


def candidates_from_value(key, value):
    found = []
    if not SOURCE_KEY.search(key):
        return found
    raw_values = [value]
    try:
        decoded = json.loads(value)
        if isinstance(decoded, str):
            raw_values.append(decoded)
        elif isinstance(decoded, dict):
            for k, v in decoded.items():
                if PATH_FIELD.search(str(k)) and isinstance(v, str):
                    found.append((v, key + ' JSON field ' + str(k)))
        elif isinstance(decoded, list):
            for item in decoded:
                if isinstance(item, str):
                    raw_values.append(item)
                elif isinstance(item, dict):
                    for k, v in item.items():
                        if PATH_FIELD.search(str(k)) and isinstance(v, str):
                            found.append((v, key + ' JSON field ' + str(k)))
    except (ValueError, TypeError):
        pass
    for raw in raw_values:
        raw = raw.strip().strip('"\'')
        if raw and (os.path.isabs(raw) or raw.startswith('./') or raw.startswith('../')):
            found.append((raw, key))
    return found


def review_file(path, provenance):
    result = {'path': str(path), 'provenance_basis': provenance}
    try:
        info = path.stat()
        if not stat.S_ISREG(info.st_mode):
            result.update(status='not_reviewed', reason='identified path is not a regular file')
            return result
        data = path.read_bytes()
        try:
            text = data.decode('utf-8')
        except UnicodeDecodeError as exc:
            result.update(status='not_reviewed', reason='not valid UTF-8 text', decode_error=str(exc), bytes=len(data))
            return result
        lines = []
        for number, line in enumerate(text.splitlines(), 1):
            if RELEVANT.search(line):
                lines.append({'line': number, 'text': line[:2000]})
        result.update(status='reviewed_as_utf8_text', bytes=len(data), sha256=__import__('hashlib').sha256(data).hexdigest(), relevant_lines=lines)
    except OSError as exc:
        result.update(status='access_error', error=str(exc))
    return result


def main():
    metadata_keys = []
    identified = {}
    for key, value in os.environ.items():
        if SOURCE_KEY.search(key):
            metadata_keys.append(key)
            for raw_path, basis in candidates_from_value(key, value):
                try:
                    path = Path(raw_path).expanduser()
                    if not path.is_absolute():
                        path = Path.cwd() / path
                    path = path.resolve(strict=False)
                    if outside_reviewed_roots(path):
                        identified.setdefault(str(path), set()).add(basis)
                except (OSError, RuntimeError) as exc:
                    identified.setdefault(raw_path, set()).add(basis + ' (path resolution error: ' + str(exc) + ')')

    reviewed = []
    errors = []
    for raw_path, bases in sorted(identified.items()):
        path = Path(raw_path)
        provenance = sorted(bases)
        try:
            if path.is_dir():
                # Directory provenance comes from explicit task-source environment metadata;
                # inspect its files without following symlinks.
                for current, dirs, files in os.walk(path, followlinks=False):
                    dirs[:] = sorted(d for d in dirs if not (Path(current) / d).is_symlink())
                    for name in sorted(files):
                        child = Path(current) / name
                        if child.is_symlink() or not outside_reviewed_roots(child):
                            continue
                        reviewed.append(review_file(child, provenance))
            elif path.exists():
                reviewed.append(review_file(path, provenance))
            else:
                errors.append({'path': raw_path, 'provenance_basis': provenance, 'error': 'identified source path does not exist'})
        except OSError as exc:
            errors.append({'path': raw_path, 'provenance_basis': provenance, 'error': str(exc)})

    print(json.dumps({
        'purpose': 'Discover and review accessible task-provided sources outside /root, /home, and /tmp using explicit environment path metadata.',
        'environment_metadata_keys': sorted(metadata_keys),
        'identified_sources': [
            {'path': path, 'provenance_basis': sorted(bases)}
            for path, bases in sorted(identified.items())
        ],
        'files_reviewed': reviewed,
        'access_errors': errors,
        'coverage': {
            'method': 'Inspected only paths explicitly named by matching task/source environment metadata; directories were traversed without following symlinks.',
            'previous_roots_excluded': ['/root', '/home', '/tmp'],
            'generated_artifacts_excluded': ['/root/scripts'],
            'provenance': 'Environment metadata is recorded as the basis; path location or file contents alone are not treated as provenance.',
            'status': 'identified sources reviewed' if identified and not errors and all(x.get('status') == 'reviewed_as_utf8_text' for x in reviewed) else 'provenance or review coverage remains insufficient',
            'limitation': 'No matching metadata, unresolved paths, undecodable files, non-regular files, or access errors leave source identity or review coverage unresolved; this does not establish absence of other task-provided sources.'
        }
    }, ensure_ascii=False))


if __name__ == '__main__':
    main()

