import hashlib
import json
import os
import re
import sys
from pathlib import Path

RELATIVE_REF = Path("llm_inputs/166ed233647466608e6491cc77fb525b4394346fe831f439e283ca0a1cfc1d0c.json")
EXPECTED_SHA256 = "166ed233647466608e6491cc77fb525b4394346fe831f439e283ca0a1cfc1d0c"
KEY_HINT = re.compile(r"source|attach|artifact|archive|input|file|path|url|uri|reference|manifest|metadata", re.I)
URI_OR_PATH = re.compile(r"(?:https?://|file://|(?:^|[\\/])[^\s\\/:]+(?:[\\/][^\s]+)+|\b[\w.-]+\.(?:json|txt|yaml|yml|zip|tar|gz|pdf|pem|pub|key)\b)", re.I)


def resolve_artifact():
    candidates = [Path.cwd() / RELATIVE_REF, Path("/") / RELATIVE_REF]
    for base in (Path("/root"), Path("/workspace"), Path("/tmp"), Path("/mnt/data")):
        candidates.append(base / RELATIVE_REF)
    seen = set()
    for candidate in candidates:
        try:
            resolved = candidate.resolve(strict=True)
            if resolved.is_file() and resolved not in seen:
                return resolved, "resolved exact supplied relative reference"
            seen.add(resolved)
        except (OSError, RuntimeError):
            pass
    # If the archive was mounted at a different root, locate only the exact
    # supplied basename within common accessible roots; record all errors.
    search_errors = []
    basename = RELATIVE_REF.name
    roots = []
    for root in (Path.cwd(), Path("/root"), Path("/workspace"), Path("/tmp"), Path("/mnt/data")):
        try:
            r = root.resolve(strict=True)
            if r.is_dir() and r not in roots:
                roots.append(r)
        except (OSError, RuntimeError):
            continue
    matches = []
    for root in roots:
        for current, dirs, files in os.walk(root, onerror=lambda e: search_errors.append(str(e))):
            dirs[:] = [d for d in dirs if d not in {".git", "proc", "sys", "dev", "node_modules", "__pycache__"}]
            if basename in files:
                p = Path(current) / basename
                try:
                    if p.is_file():
                        matches.append(p.resolve())
                except OSError as e:
                    search_errors.append(f"{p}: {e}")
    unique = sorted(set(matches), key=str)
    return (unique[0], "exact basename found by search; path differs from supplied reference") if len(unique) == 1 else (None, "not found" if not unique else "ambiguous exact-basename matches: " + ", ".join(map(str, unique))), search_errors


def collect_refs(obj):
    found = []
    def visit(value, loc="$", key_hint=False):
        if isinstance(value, dict):
            for key, item in value.items():
                visit(item, f"{loc}.{key}", bool(KEY_HINT.search(str(key))))
        elif isinstance(value, list):
            for i, item in enumerate(value):
                visit(item, f"{loc}[{i}]", key_hint)
        elif isinstance(value, str):
            if key_hint or URI_OR_PATH.search(value):
                found.append({"location": loc, "value": value})
    visit(obj)
    return found


def associated_metadata(directory, artifact_path, digest):
    examined = []
    findings = []
    errors = []
    if not directory or not directory.is_dir():
        return examined, findings, errors
    try:
        entries = sorted(directory.iterdir(), key=lambda p: p.name)
    except OSError as e:
        return examined, findings, [f"cannot list {directory}: {e}"]
    stem = artifact_path.name
    stem_no_ext = artifact_path.stem
    for p in entries:
        if not p.is_file() or p == artifact_path:
            continue
        name = p.name.lower()
        # Inspect only likely sidecars/manifests and same-stem metadata.
        likely = (stem_no_ext.lower() in name or
                  (any(word in name for word in ("manifest", "metadata", "index", "archive")) and p.suffix.lower() in {".json", ".jsonl", ".txt", ".yaml", ".yml"}))
        if not likely:
            continue
        examined.append(str(p))
        try:
            raw = p.read_bytes()
        except OSError as e:
            errors.append(f"{p}: {e}")
            continue
        text = raw.decode("utf-8", errors="replace")
        # A candidate is associated only if its contents explicitly refer to
        # the artifact basename or its computed/supplied digest.
        if stem in text or stem_no_ext in text or digest in text or EXPECTED_SHA256 in text:
            record = {"path": str(p), "bytes": len(raw), "sha256": hashlib.sha256(raw).hexdigest(), "association_basis": "candidate contents mention artifact filename or digest"}
            try:
                parsed = json.loads(text)
                record["format"] = "JSON"
                record["references"] = collect_refs(parsed)
            except (json.JSONDecodeError, UnicodeError):
                record["format"] = "text; matching lines"
                record["matching_lines"] = [line for line in text.splitlines() if stem in line or stem_no_ext in line or digest in line or EXPECTED_SHA256 in line]
            findings.append(record)
    return examined, findings, errors


def main():
    resolved_result = resolve_artifact()
    if len(resolved_result) == 3:
        artifact, resolution, search_errors = resolved_result
    else:
        artifact, resolution = resolved_result
        search_errors = []
    report = {
        "supplied_artifact_reference": str(RELATIVE_REF),
        "supplied_archive_sha256": EXPECTED_SHA256,
        "resolution": resolution,
        "artifact_accessible": artifact is not None,
        "search_errors": search_errors,
        "artifact": None,
        "adjacent_directory_examined": None,
        "adjacent_entries": [],
        "metadata_candidates_examined": [],
        "associated_metadata": [],
        "metadata_errors": [],
        "coverage": "Only the exact referenced artifact, its immediate directory listing, and likely associated sidecar/manifest candidates are examined. This cannot establish that unreferenced sources or metadata elsewhere do not exist."
    }
    if artifact is None:
        print(json.dumps(report, ensure_ascii=False, indent=2))
        return
    try:
        raw = artifact.read_bytes()
        digest = hashlib.sha256(raw).hexdigest()
        record = {"resolved_path": str(artifact), "provenance": "task-supplied archive reference in the run input; file contents are observed only if read succeeds", "bytes": len(raw), "sha256": digest, "matches_supplied_sha256": digest == EXPECTED_SHA256}
        try:
            data = json.loads(raw.decode("utf-8"))
            record["parse_status"] = "parsed JSON"
            record["top_level_type"] = type(data).__name__
            record["source_and_attachment_references"] = collect_refs(data)
        except (UnicodeDecodeError, json.JSONDecodeError) as e:
            record["parse_status"] = "not parseable as UTF-8 JSON"
            record["parse_error"] = str(e)
            record["references"] = []
        report["artifact"] = record
        parent = artifact.parent
        report["adjacent_directory_examined"] = str(parent)
        try:
            report["adjacent_entries"] = sorted(p.name + ("/" if p.is_dir() else "") for p in parent.iterdir())
        except OSError as e:
            report["metadata_errors"].append(f"cannot list adjacent directory: {e}")
        examined, findings, errors = associated_metadata(parent, artifact, digest)
        report["metadata_candidates_examined"] = examined
        report["associated_metadata"] = findings
        report["metadata_errors"].extend(errors)
    except OSError as e:
        report["artifact_read_error"] = f"{type(e).__name__}: {e}"
    print(json.dumps(report, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

