import hashlib
import json
import os
from pathlib import Path

ARTIFACT_REF = Path("llm_inputs/f950897a2d7cfab903b92de442d08a88c420058f57caaea409e59547c4336909.json")
EXPECTED_SHA256 = "f950897a2d7cfab903b92de442d08a88c420058f57caaea409e59547c4336909"
METADATA_TERMS = ("archive", "entry", "attachment", "manifest", "metadata")


def candidate_paths():
    cwd = Path.cwd().resolve()
    seen = set()
    for base in (cwd, *cwd.parents):
        candidate = base / ARTIFACT_REF
        key = str(candidate)
        if key not in seen:
            seen.add(key)
            yield candidate


def referenced_fields(value, location="$", found=None):
    if found is None:
        found = []
    if isinstance(value, dict):
        for key, item in value.items():
            key_text = str(key).lower()
            child_location = location + "." + str(key)
            if any(term in key_text for term in ("source", "reference", "attachment", "file", "path")):
                found.append({"json_location": child_location, "key": str(key), "value": item})
            referenced_fields(item, child_location, found)
    elif isinstance(value, list):
        for index, item in enumerate(value):
            referenced_fields(item, "%s[%d]" % (location, index), found)
    return found


def inspect_json_file(path):
    record = {"path": str(path), "read_status": "unread"}
    try:
        raw = path.read_bytes()
    except Exception as exc:
        record.update({"read_status": "error", "error": "%s: %s" % (type(exc).__name__, exc)})
        return record
    record["sha256"] = hashlib.sha256(raw).hexdigest()
    record["byte_length"] = len(raw)
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        record.update({"read_status": "not_utf8", "decode_error": str(exc), "contents_utf8_replacement": raw.decode("utf-8", errors="replace")})
        return record
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        record.update({"read_status": "read_not_json", "parse_error": str(exc), "contents": text})
        return record
    record.update({"read_status": "read_and_parsed_json", "contents": data})
    return record


def main():
    result = {
        "purpose": "Inspect the supplied archived original task-input artifact and associated archive-style sibling metadata; no external commands are run.",
        "supplied_artifact_reference": str(ARTIFACT_REF),
        "supplied_sha256": EXPECTED_SHA256,
        "working_directory": str(Path.cwd()),
        "candidate_paths_checked": [],
        "artifact": None,
        "artifact_reference_hash_matches_supplied": None,
        "source_or_attachment_related_fields": [],
        "artifact_directory_metadata_candidates": [],
        "coverage": "Checks the exact supplied relative path under the current directory and each ancestor, then examines matching metadata-named regular files directly beside the resolved artifact. It does not search the entire filesystem or establish that unreferenced sources do not exist.",
    }
    artifact_path = None
    for candidate in candidate_paths():
        result["candidate_paths_checked"].append(str(candidate))
        try:
            if candidate.is_file():
                artifact_path = candidate.resolve()
                break
        except OSError as exc:
            result["candidate_path_error"] = "%s: %s" % (candidate, exc)
    if artifact_path is None:
        result["artifact"] = {"read_status": "not_found_at_checked_paths"}
        print(json.dumps(result, ensure_ascii=False, sort_keys=True))
        return

    artifact_record = inspect_json_file(artifact_path)
    result["artifact"] = artifact_record
    if "sha256" in artifact_record:
        result["artifact_reference_hash_matches_supplied"] = artifact_record["sha256"] == EXPECTED_SHA256
    contents = artifact_record.get("contents")
    if contents is not None:
        result["source_or_attachment_related_fields"] = referenced_fields(contents)

    metadata_records = []
    try:
        siblings = sorted(artifact_path.parent.iterdir(), key=lambda p: p.name)
    except OSError as exc:
        result["artifact_directory_listing_error"] = "%s: %s" % (type(exc).__name__, exc)
        siblings = []
    for sibling in siblings:
        name = sibling.name.lower()
        if sibling == artifact_path or not any(term in name for term in METADATA_TERMS):
            continue
        try:
            if sibling.is_file():
                metadata_records.append(inspect_json_file(sibling))
        except OSError as exc:
            metadata_records.append({"path": str(sibling), "read_status": "stat_error", "error": "%s: %s" % (type(exc).__name__, exc)})
    result["artifact_directory_metadata_candidates"] = metadata_records
    print(json.dumps(result, ensure_ascii=False, sort_keys=True))


if __name__ == "__main__":
    main()

