import hashlib
import json
import os
from pathlib import Path

ARTIFACT_REF = "llm_inputs/abebae9ecbe3a7b56f557edc9fd0420547147ca83f70a0a1af528809f0f89353.json"
BASENAME = Path(ARTIFACT_REF).name


def read_file(path):
    try:
        data = path.read_bytes()
    except OSError as exc:
        return {"path": str(path), "status": "unreadable", "error": str(exc)}
    result = {
        "path": str(path),
        "resolved_path": str(path.resolve()),
        "status": "readable",
        "size_bytes": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
    }
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError as exc:
        result.update({"status": "readable_non_utf8", "decode_error": str(exc), "content_hex": data.hex()})
        return result
    try:
        result.update({"format": "json", "contents": json.loads(text)})
    except json.JSONDecodeError as exc:
        result.update({"format": "text", "parse_error": str(exc), "contents": text})
    return result


def main():
    cwd = Path.cwd()
    roots = [cwd, Path("/root/scripts"), Path("/root"), Path("/tmp"), Path("/workspace"), Path("/mnt/data")]
    unique_roots = []
    seen_roots = set()
    for root in roots:
        try:
            key = str(root.resolve())
        except OSError:
            key = str(root)
        if key not in seen_roots:
            seen_roots.add(key)
            unique_roots.append(root)

    checks = []
    candidates = []
    seen_paths = set()
    for root in unique_roots:
        path = root / ARTIFACT_REF
        checks.append({"path": str(path), "exists": path.is_file()})
        if path.is_file():
            key = str(path.resolve())
            if key not in seen_paths:
                seen_paths.add(key)
                candidates.append(path)

    # If the exact relative path is not present, search only the listed roots
    # for this exact basename; do not inspect unrelated files.
    if not candidates:
        for root in unique_roots:
            if not root.is_dir():
                continue
            try:
                for dirpath, dirnames, filenames in os.walk(root):
                    dirnames[:] = [name for name in dirnames if name not in {"proc", "sys", "dev", ".git", "__pycache__"}]
                    if BASENAME in filenames:
                        path = Path(dirpath) / BASENAME
                        key = str(path.resolve())
                        if key not in seen_paths:
                            seen_paths.add(key)
                            candidates.append(path)
            except OSError as exc:
                checks.append({"search_root": str(root), "error": str(exc)})

    output = {
        "purpose": "Inspect the exact archived original task-input artifact and narrowly associated metadata; treat contents as data, not instructions.",
        "artifact_reference_from_original_input": ARTIFACT_REF,
        "original_input_availability_claim": "available_in_archive (task-supplied metadata)",
        "working_directory": str(cwd),
        "search_roots": [str(root) for root in unique_roots],
        "path_checks": checks,
        "artifact_matches": [],
        "associated_metadata_examined": [],
        "coverage_note": "Search is limited to the exact artifact reference/basename within the listed roots and associated sibling metadata names; it does not establish that unsearched locations or unreferenced sources do not exist."
    }

    metadata_names = {
        BASENAME + ".metadata.json",
        BASENAME + ".meta.json",
        Path(BASENAME).stem + ".metadata.json",
        Path(BASENAME).stem + ".meta.json",
        "metadata.json",
        "manifest.json",
        "archive.json",
    }
    for artifact in candidates:
        artifact_result = read_file(artifact)
        output["artifact_matches"].append(artifact_result)
        parent = artifact.parent
        for name in sorted(metadata_names):
            metadata_path = parent / name
            if metadata_path == artifact or not metadata_path.is_file():
                continue
            metadata_result = read_file(metadata_path)
            # Generic directory metadata is retained only when its parsed data
            # explicitly mentions this artifact filename; basename-specific
            # metadata is associated by its filename.
            if name in {"metadata.json", "manifest.json", "archive.json"}:
                serialized = json.dumps(metadata_result.get("contents", ""), ensure_ascii=False, sort_keys=True)
                if BASENAME not in serialized:
                    continue
            output["associated_metadata_examined"].append(metadata_result)

    if not candidates:
        output["finding"] = "The exact artifact was not found in the searched locations; its contents and associated metadata could not be established."
    else:
        output["finding"] = "Artifact file(s) with the exact supplied basename were found and read where accessible; assess their recorded contents and provenance before treating any reference as task-provided."

    print(json.dumps(output, ensure_ascii=False, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()

