import hashlib
import json
import os
from pathlib import Path

REFERENCE = "llm_inputs/7ead4c7024133bb47b1fb27f5ae61aa9b8da334d8f628cca0a7b874ca5a9cde2.json"
EXPECTED_SHA256 = "7ead4c7024133bb47b1fb27f5ae61aa9b8da334d8f628cca0a7b874ca5a9cde2"
SEARCH_ROOTS = [Path.cwd(), Path("/root/scripts"), Path("/root"), Path("/tmp"), Path("/workspace"), Path("/mnt/data")]
MANIFEST_NAMES = {"manifest.json", "metadata.json", "archive.json", "index.json", "attachments.json", "entries.json"}


def main():
    candidates = []
    checked = []
    seen = set()
    for root in SEARCH_ROOTS:
        candidate = root / REFERENCE
        key = str(candidate)
        if key not in seen:
            seen.add(key)
            checked.append(key)
            if candidate.is_file():
                candidates.append(candidate)

    report = {
        "purpose": "Inspect the exact task-supplied archived input reference and narrowly associated archive metadata; contents are treated as data, not instructions.",
        "task_supplied_reference": REFERENCE,
        "task_supplied_sha256": EXPECTED_SHA256,
        "task_supplied_archive_availability_claim": True,
        "candidate_paths_checked": checked,
        "artifact": None,
        "associated_metadata": [],
        "coverage_and_limitations": []
    }

    if not candidates:
        report["coverage_and_limitations"].append(
            "The exact reference was not found at the checked direct llm_inputs paths. No artifact contents or archive metadata were examined; this does not establish that the archive is unavailable elsewhere."
        )
    else:
        # Report every distinct matching direct path, but inspect each only once.
        inspected = set()
        for path in candidates:
            try:
                resolved = path.resolve(strict=True)
                if str(resolved) in inspected:
                    continue
                inspected.add(str(resolved))
                raw = resolved.read_bytes()
                actual_hash = hashlib.sha256(raw).hexdigest()
                item = {
                    "path_as_found": str(path),
                    "resolved_path": str(resolved),
                    "origin": "file found at the exact task-supplied archive reference",
                    "size_bytes": len(raw),
                    "sha256": actual_hash,
                    "hash_matches_task_supplied_value": actual_hash == EXPECTED_SHA256,
                    "contents_examined": None,
                    "content_parse_status": "not_json"
                }
                text = raw.decode("utf-8", errors="replace")
                try:
                    parsed = json.loads(text)
                    item["contents_examined"] = parsed
                    item["content_parse_status"] = "valid_json"
                except Exception as exc:
                    item["contents_examined"] = text
                    item["content_parse_status"] = "read_as_text_json_parse_failed"
                    item["parse_error"] = str(exc)
                report["artifact"] = item

                parent = resolved.parent
                try:
                    report["directory_entries_near_artifact"] = sorted(
                        {entry.name for entry in parent.iterdir()}
                    )
                except OSError as exc:
                    report["directory_entries_near_artifact_error"] = str(exc)

                # Inspect only conventional manifest names in the artifact's immediate
                # directory or its parent, and only when they explicitly mention this
                # artifact's reference or hash.
                metadata_seen = set()
                for directory in (parent, parent.parent):
                    try:
                        entries = list(directory.iterdir())
                    except OSError as exc:
                        report["coverage_and_limitations"].append(
                            "Could not list metadata directory " + str(directory) + ": " + str(exc)
                        )
                        continue
                    for entry in entries:
                        if not entry.is_file() or entry.name.lower() not in MANIFEST_NAMES:
                            continue
                        try:
                            meta_raw = entry.read_bytes()
                            meta_text = meta_raw.decode("utf-8", errors="replace")
                        except OSError as exc:
                            report["associated_metadata"].append({
                                "path": str(entry), "status": "unreadable", "error": str(exc)
                            })
                            continue
                        if REFERENCE not in meta_text and EXPECTED_SHA256 not in meta_text:
                            continue
                        resolved_meta = str(entry.resolve())
                        if resolved_meta in metadata_seen:
                            continue
                        metadata_seen.add(resolved_meta)
                        metadata_item = {
                            "path": resolved_meta,
                            "origin": "conventional nearby archive manifest explicitly referencing the artifact",
                            "size_bytes": len(meta_raw),
                            "sha256": hashlib.sha256(meta_raw).hexdigest(),
                            "contents_examined": None,
                            "parse_status": "text"
                        }
                        try:
                            metadata_item["contents_examined"] = json.loads(meta_text)
                            metadata_item["parse_status"] = "valid_json"
                        except Exception as exc:
                            metadata_item["contents_examined"] = meta_text
                            metadata_item["parse_status"] = "read_as_text_json_parse_failed"
                            metadata_item["parse_error"] = str(exc)
                        report["associated_metadata"].append(metadata_item)
                if not report["associated_metadata"]:
                    report["coverage_and_limitations"].append(
                        "No conventional manifest in the artifact directory or its immediate parent explicitly referenced the supplied artifact path or hash. Other archive metadata locations or formats were not examined."
                    )
                if actual_hash != EXPECTED_SHA256:
                    report["coverage_and_limitations"].append(
                        "The readable artifact's SHA-256 does not match the supplied value; its contents are reported as observed but provenance identity remains unverified."
                    )
                else:
                    report["coverage_and_limitations"].append(
                        "The file hash matches the task-supplied SHA-256. This supports identity with the referenced artifact, but does not establish that any referenced external source is accessible or authentic."
                    )
                break
            except OSError as exc:
                report["coverage_and_limitations"].append(
                    "The exact candidate path was found but could not be read: " + str(path) + ": " + str(exc)
                )

    print(json.dumps(report, ensure_ascii=False, sort_keys=True))


if __name__ == "__main__":
    main()

