import hashlib
import json
import os
import sys
from pathlib import Path

REFERENCE = "llm_inputs/04cccb1da05a13e47f873d44286254543cbf9b249b972803a6e08dd51857f697.json"
EXPECTED_SHA256 = "04cccb1da05a13e47f873d44286254543cbf9b249b972803a6e08dd51857f697"
BASENAME = Path(REFERENCE).name

# Check the exact relative reference and common direct llm_inputs locations.
# These are locations to test, not claims that the artifact exists there.
candidates = [
    Path.cwd() / REFERENCE,
    Path("/root/scripts") / REFERENCE,
    Path("/root") / REFERENCE,
    Path("/tmp") / REFERENCE,
    Path("/workspace") / REFERENCE,
    Path("/mnt/data") / REFERENCE,
]
checked = []
seen = set()
found = []
for candidate in candidates:
    key = str(candidate)
    if key in seen:
        continue
    seen.add(key)
    entry = {"path": key, "exists": False}
    try:
        exists = candidate.is_file()
        entry["exists"] = exists
        if exists:
            found.append(candidate)
    except OSError as exc:
        entry["error"] = f"{type(exc).__name__}: {exc}"
    checked.append(entry)

records = []
associated = []
for path in found:
    record = {
        "reference": REFERENCE,
        "provenance": "The reference and expected digest came from the supplied original_input metadata.",
        "path": str(path),
    }
    try:
        raw = path.read_bytes()
        digest = hashlib.sha256(raw).hexdigest()
        record["bytes_read"] = len(raw)
        record["computed_sha256"] = digest
        record["expected_sha256"] = EXPECTED_SHA256
        record["sha256_matches_expected"] = digest == EXPECTED_SHA256
        try:
            text = raw.decode("utf-8")
            try:
                record["content"] = json.loads(text)
                record["content_format"] = "valid UTF-8 JSON"
            except json.JSONDecodeError as exc:
                record["content"] = text
                record["content_format"] = "UTF-8 text; not valid JSON"
                record["content_parse_error"] = str(exc)
        except UnicodeDecodeError as exc:
            import base64
            record["content_base64"] = base64.b64encode(raw).decode("ascii")
            record["content_format"] = "non-UTF-8 bytes; base64 encoded"
            record["content_decode_error"] = str(exc)
    except OSError as exc:
        record["read_error"] = f"{type(exc).__name__}: {exc}"
    records.append(record)

    # Examine only conventional sidecars and manifest entries directly adjacent
    # to a found artifact, and include manifest material only when it references
    # this exact artifact name or reference.
    sidecars = [
        path.with_name(path.name + ".metadata.json"),
        path.with_name(path.name + ".meta.json"),
        path.with_name(path.name + ".attachments.json"),
    ]
    for sidecar in sidecars:
        try:
            if sidecar.is_file():
                raw_sidecar = sidecar.read_bytes()
                item = {"path": str(sidecar), "bytes_read": len(raw_sidecar),
                        "sha256": hashlib.sha256(raw_sidecar).hexdigest()}
                try:
                    item["content"] = json.loads(raw_sidecar.decode("utf-8"))
                    item["content_format"] = "valid UTF-8 JSON"
                except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                    item["content_format"] = "unparsed"
                    item["error"] = f"{type(exc).__name__}: {exc}"
                associated.append(item)
        except OSError as exc:
            associated.append({"path": str(sidecar), "error": f"{type(exc).__name__}: {exc}"})

    for manifest_name in ("manifest.json", "index.json", "attachments.json"):
        manifest = path.parent / manifest_name
        try:
            if not manifest.is_file():
                continue
            raw_manifest = manifest.read_bytes()
            parsed = json.loads(raw_manifest.decode("utf-8"))
