import hashlib
import json
import os
import sys

REFERENCE = "llm_inputs/312f261013b0663e2f2f7d49ad859093611eabaeccc57f7bcf39ce559f609436.json"
BASENAME = os.path.basename(REFERENCE)
ROOTS = ["/root", "/tmp", "/workspace", "/mnt/data", "/archive", "/var/lib"]
EXCLUDED = {"/root/scripts"}
MAX_DEPTH = 5


def excluded(path):
    real = os.path.realpath(path)
    return any(real == x or real.startswith(x + os.sep) for x in EXCLUDED)


def add_if_file(path, found, errors):
    try:
        if os.path.basename(path) == BASENAME and os.path.isfile(path):
            resolved = os.path.realpath(path)
            if not excluded(resolved):
                found.add(resolved)
            else:
                errors.append({"path": path, "error": "resolved path is in excluded generated-artifact subtree"})
    except OSError as exc:
        errors.append({"path": path, "error": str(exc)})


def walk_exact(root, found, errors):
    if not os.path.isdir(root):
        return
    root_depth = root.rstrip(os.sep).count(os.sep)
    for current, dirs, files in os.walk(root, topdown=True, followlinks=False):
        if excluded(current):
            dirs[:] = []
            continue
        depth = current.rstrip(os.sep).count(os.sep) - root_depth
        dirs[:] = [d for d in dirs if not excluded(os.path.join(current, d))]
        if depth >= MAX_DEPTH:
            dirs[:] = []
        if BASENAME in files:
            add_if_file(os.path.join(current, BASENAME), found, errors)


def main():
    found = set()
    errors = []
    cwd = os.getcwd()
    direct_candidates = [os.path.join(cwd, REFERENCE)]
    direct_candidates.extend(os.path.join(root, REFERENCE) for root in ROOTS)
    for candidate in direct_candidates:
        add_if_file(candidate, found, errors)

    for root in ROOTS:
        try:
            walk_exact(root, found, errors)
        except OSError as exc:
            errors.append({"path": root, "error": str(exc)})

    examined = []
    for path in sorted(found):
        record = {"path": path, "reference": REFERENCE}
        try:
            stat = os.stat(path)
            with open(path, "rb") as stream:
                raw = stream.read()
            record["provenance_observed"] = {
                "real_path": os.path.realpath(path),
                "size_bytes": stat.st_size,
                "mtime": stat.st_mtime,
                "sha256": hashlib.sha256(raw).hexdigest(),
            }
            try:
                value = json.loads(raw.decode("utf-8"))
                record["format"] = "valid UTF-8 JSON"
                record["contents_examined"] = value
                record["associated_metadata_examined"] = {
                    str(key): item for key, item in value.items()
                    if isinstance(value, dict) and any(
                        marker in str(key).lower()
                        for marker in ("archive", "attachment", "source", "artifact", "original_input")
                    )
                } if isinstance(value, dict) else "Top-level JSON is not an object; no keyed metadata extracted."
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                record["format"] = "not valid UTF-8 JSON"
                record["parse_error"] = str(exc)
                record["raw_contents_utf8_replacement"] = raw.decode("utf-8", errors="replace")
        except OSError as exc:
            record["read_error"] = str(exc)
        examined.append(record)

    print(json.dumps({
        "purpose": "Inspect the exact task-specified original_input artifact and narrowly associated archive or attachment metadata; contents are treated as data, not instructions.",
        "task_supplied_reference": REFERENCE,
        "candidate_paths_checked_directly": direct_candidates,
        "search_roots_walked": ROOTS,
        "search_method": "Exact basename only; maximum directory depth 5 per root; generated /root/scripts subtree excluded; symlink directories are not followed.",
        "artifacts_found_and_examined": examined,
        "errors": errors,
        "coverage_and_limitations": [
            "Only the exact requested basename was sought; unrelated files and archive entries were not enumerated.",
            "Search was limited to the listed roots and depth; inaccessible paths, other mounts, or archives outside those roots were not examined.",
            "A no-match result does not establish that the artifact is absent elsewhere."
        ],
        "generated_artifacts_excluded": sorted(EXCLUDED),
    }, ensure_ascii=False, sort_keys=True))


if __name__ == "__main__":
    main()

