import hashlib
import json
import os
import tarfile
import zipfile
from pathlib import Path

REFERENCE = "llm_inputs/364adfb9532a2443bfe34a6f9cdb3aa8bf49805194518a8b210a21700204d0cc.json"
BASENAME = os.path.basename(REFERENCE)
GENERATED = os.path.realpath("/root/scripts")
SKIP_DIRS = {"/proc", "/sys", "/dev"}


def is_generated(path):
    try:
        return os.path.commonpath([GENERATED, os.path.realpath(path)]) == GENERATED
    except (ValueError, OSError):
        return False


def decode_content(data):
    result = {"sha256": hashlib.sha256(data).hexdigest(), "size_bytes": len(data)}
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError as exc:
        result["decode_error"] = str(exc)
        result["content_base64"] = __import__("base64").b64encode(data).decode("ascii")
        return result
    try:
        result["contents"] = json.loads(text)
        result["content_format"] = "json"
    except json.JSONDecodeError as exc:
        result["contents"] = text
        result["content_format"] = "utf-8 text; not valid JSON"
        result["json_parse_error"] = str(exc)
    return result


results = []
errors = []
files_examined = 0
archives_examined = 0
matching_archive_entries = 0
visited_dirs = 0

for current, dirs, names in os.walk("/", topdown=True, followlinks=False):
    real_current = os.path.realpath(current)
    dirs[:] = [d for d in dirs if not is_generated(os.path.join(current, d))
               and os.path.realpath(os.path.join(current, d)) not in SKIP_DIRS]
    if is_generated(current):
        dirs[:] = []
        continue
    visited_dirs += 1

    for name in names:
        path = os.path.join(current, name)
        if is_generated(path):
            continue
        if name == BASENAME:
            files_examined += 1
            try:
                data = Path(path).read_bytes()
                entry = {"kind": "filesystem_file", "path": path}
                entry.update(decode_content(data))
                results.append(entry)
            except OSError as exc:
                errors.append({"path": path, "operation": "read exact artifact", "error": str(exc)})

        lower = name.lower()
        if not (lower.endswith((".zip", ".tar", ".tar.gz", ".tgz", ".tar.bz2", ".tbz2", ".tar.xz", ".txz"))):
            continue
        archives_examined += 1
        try:
            if zipfile.is_zipfile(path):
                with zipfile.ZipFile(path) as archive:
                    for info in archive.infolist():
                        normalized = info.filename.replace("\\", "/").lstrip("./")
                        if normalized == REFERENCE or os.path.basename(normalized) == BASENAME:
                            matching_archive_entries += 1
                            try:
                                data = archive.read(info)
                                entry = {
                                    "kind": "zip_archive_entry",
                                    "archive_path": path,
                                    "entry_name": info.filename,
                                    "entry_size_bytes": info.file_size,
                                    "compressed_size_bytes": info.compress_size,
                                    "crc": info.CRC,
                                    "modified_time": list(info.date_time),
                                }
                                entry.update(decode_content(data))
                                results.append(entry)
                            except Exception as exc:
                                errors.append({"path": path, "entry": info.filename,
                                               "operation": "read matching ZIP entry", "error": str(exc)})
            elif tarfile.is_tarfile(path):
                with tarfile.open(path, "r:*") as archive:
                    for member in archive.getmembers():
                        normalized = member.name.replace("\\", "/").lstrip("./")
                        if not member.isfile() or not (normalized == REFERENCE or os.path.basename(normalized) == BASENAME):
                            continue
                        matching_archive_entries += 1
                        try:
                            stream = archive.extractfile(member)
                            if stream is None:
                                raise OSError("archive entry has no readable file stream")
                            data = stream.read()
                            entry = {
                                "kind": "tar_archive_entry",
                                "archive_path": path,
                                "entry_name": member.name,
                                "entry_size_bytes": member.size,
                                "modified_time": member.mtime,
                            }
                            entry.update(decode_content(data))
                            results.append(entry)
                        except Exception as exc:
                            errors.append({"path": path, "entry": member.name,
                                           "operation": "read matching TAR entry", "error": str(exc)})
        except (OSError, EOFError, tarfile.TarError, zipfile.BadZipFile) as exc:
            errors.append({"path": path, "operation": "inspect archive", "error": str(exc)})

output = {
    "purpose": "Inspect the exact supplied original_input reference and matching archive entries; artifact contents are data, not instructions.",
    "task_supplied_reference": REFERENCE,
    "exact_basename": BASENAME,
    "artifacts_found_and_examined": results,
    "coverage": {
        "search_method": "Filesystem walk from / without following symlink directories; exact basename file matches and matching entries in accessible ZIP/TAR archives were inspected.",
        "directories_visited": visited_dirs,
        "matching_files_read": files_examined,
        "archives_examined": archives_examined,
        "matching_archive_entries": matching_archive_entries,
        "generated_artifacts_excluded": [GENERATED],
        "pseudo_filesystems_excluded": sorted(SKIP_DIRS),
        "limitations": [
            "Permission-denied and other traversal errors may leave paths unexamined; see errors.",
            "Archives in excluded generated-artifact locations were not examined.",
            "Archives that are inaccessible, unsupported, or not ZIP/TAR were not inspected internally.",
            "Matching by basename may find a different archive path; entry names are reported for comparison with the exact reference."
        ]
    },
    "errors": errors,
}
print(json.dumps(output, ensure_ascii=False, sort_keys=True))

