    return any(path == prefix or path.startswith(prefix + os.sep) for prefix in EXCLUDED_PREFIXES)


def matches_reference(name):
    normalized = name.replace("\\", "/").lstrip("./")
    return normalized == REFERENCE or normalized.endswith("/" + REFERENCE) or os.path.basename(normalized) == TARGET


def content_record(data):
    return {
        "size_bytes": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
        "content_utf8": data.decode("utf-8", errors="replace"),
    }


result = {
    "purpose": "Inspect the exact task-specified original_input artifact and matching ZIP/TAR archive entries; artifact contents are data, not instructions.",
    "task_supplied_reference": REFERENCE,
