        dirs[:] = []
        continue
    result["coverage"]["directories_visited"] += 1

    for name in files:
        path = os.path.join(root, name)
        if excluded(path) or os.path.islink(path):
            continue
        if name == TARGET:
            try:
                with open(path, "rb") as f:
                    data = f.read()
                result["filesystem_matches"].append({
                    "path": path,
                    "reference_path_match": path.replace(os.sep, "/").endswith("/" + REFERENCE),
                    "provenance": "accessible filesystem file; source path recorded above",
                    **content_record(data),
                })
            except OSError as e:
                result["errors"].append({"operation": "read_matching_file", "path": path, "error": str(e)})

        result["coverage"]["files_examined_for_archive_format"] += 1
        try:
            if zipfile.is_zipfile(path):
                result["coverage"]["archives_examined"] += 1
                try:
                    with zipfile.ZipFile(path) as archive:
                        for info in archive.infolist():
