                                except Exception as e:
                                    result["errors"].append({"operation": "read_zip_entry", "archive": path, "entry": info.filename, "error": str(e)})
                except Exception as e:
                    result["errors"].append({"operation": "inspect_zip", "path": path, "error": str(e)})
            elif tarfile.is_tarfile(path):
                result["coverage"]["archives_examined"] += 1
                try:
                    with tarfile.open(path, mode="r:*") as archive:
                        for info in archive.getmembers():
                            if matches_reference(info.name) and info.isfile():
                                try:
                                    member = archive.extractfile(info)
                                    if member is None:
                                        raise OSError("archive entry has no readable file stream")
                                    data = member.read()
                                    result["archive_matches"].append({
                                        "archive_path": path,
                                        "entry_name": info.name,
                                        "reference_path_match": info.name.replace("\\", "/").lstrip("./").endswith(REFERENCE),
                                        "entry_metadata": {"size": info.size, "mtime": info.mtime, "mode": info.mode, "uid": info.uid, "gid": info.gid, "type": info.type.decode("ascii", errors="replace") if isinstance(info.type, bytes) else str(info.type)},
                                        **content_record(data),
                                    })
                                except Exception as e:
                                    result["errors"].append({"operation": "read_tar_entry", "archive": path, "entry": info.name, "error": str(e)})
                except Exception as e:
