import hashlib
import json
import os
import sys
import tarfile
import zipfile
from pathlib import Path

RELATIVE = "llm_inputs/0705c27d2edccd05e164091d60445075c2c6eb0f7ad4cae691ae6fc72f3cab2e.json"
BASENAME = os.path.basename(RELATIVE)
SKIP_DIRS = {"proc", "sys", "dev", "run", ".cache", "node_modules"}
SKIP_PREFIXES = ("/root/scripts",)
ARCHIVE_SUFFIXES = (".zip", ".tar", ".tgz", ".tar.gz", ".tar.bz2", ".tar.xz", ".tbz", ".tbz2", ".txz")
MAX_ARCHIVE_MEMBER = 64 * 1024 * 1024


def is_generated_path(path):
    p = os.path.realpath(path)
    return any(p == prefix or p.startswith(prefix + os.sep) for prefix in SKIP_PREFIXES)


def parse_content(data):
    text = data.decode("utf-8", errors="replace")
    try:
        return {"status": "parsed_json", "content": json.loads(text)}
    except Exception as exc:
        return {"status": "not_valid_json", "error": str(exc), "text": text}


def record(label, data):
    result = {
        "location": label,
        "size_bytes": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
    }
    result.update(parse_content(data))
    return result


def norm_member(name):
    return name.replace("\\", "/").lstrip("./")


def archive_candidates(path):
    lower = path.lower()
    if lower.endswith(ARCHIVE_SUFFIXES):
        return True
    try:
        with open(path, "rb") as f:
            head = f.read(512)
        return head.startswith(b"PK\x03\x04") or head.startswith(b"PK\x05\x06") or (len(head) >= 262 and head[257:262] == b"ustar")
    except OSError:
        return False


def main():
    matches = []
    errors = []
    scanned_dirs = 0
    scanned_files = 0
    archives_checked = 0
    roots = ["/"]
    seen_dirs = set()

    for root in roots:
        for current, dirs, files in os.walk(root, topdown=True, followlinks=False):
            real_current = os.path.realpath(current)
            if real_current in seen_dirs or is_generated_path(current):
                dirs[:] = []
                continue
            seen_dirs.add(real_current)
            scanned_dirs += 1
            dirs[:] = [d for d in dirs if d not in SKIP_DIRS and not is_generated_path(os.path.join(current, d))]
            for name in files:
                path = os.path.join(current, name)
                scanned_files += 1
                if is_generated_path(path):
                    continue
                if name == BASENAME and os.path.basename(os.path.dirname(path)) == "llm_inputs":
                    try:
                        with open(path, "rb") as f:
                            matches.append(record(path, f.read()))
                    except OSError as exc:
                        errors.append({"path": path, "operation": "read_exact_file", "error": str(exc)})
                if not archive_candidates(path):
                    continue
                archives_checked += 1
                try:
                    if zipfile.is_zipfile(path):
                        with zipfile.ZipFile(path) as archive:
                            for info in archive.infolist():
                                if norm_member(info.filename) != RELATIVE or info.is_dir():
                                    continue
                                if info.file_size > MAX_ARCHIVE_MEMBER:
                                    errors.append({"path": path, "member": info.filename, "operation": "read_archive_member", "error": "member exceeds 64 MiB review limit"})
                                    continue
                                try:
                                    matches.append(record(path + "!" + info.filename, archive.read(info)))
                                except Exception as exc:
                                    errors.append({"path": path, "member": info.filename, "operation": "read_archive_member", "error": str(exc)})
                    elif tarfile.is_tarfile(path):
                        with tarfile.open(path, mode="r:*") as archive:
                            for member in archive.getmembers():
                                if norm_member(member.name) != RELATIVE or not member.isfile():
                                    continue
                                if member.size > MAX_ARCHIVE_MEMBER:
                                    errors.append({"path": path, "member": member.name, "operation": "read_archive_member", "error": "member exceeds 64 MiB review limit"})
                                    continue
                                stream = archive.extractfile(member)
                                if stream is None:
                                    errors.append({"path": path, "member": member.name, "operation": "read_archive_member", "error": "member did not yield a readable stream"})
                                    continue
                                try:
                                    matches.append(record(path + "!" + member.name, stream.read()))
                                except Exception as exc:
                                    errors.append({"path": path, "member": member.name, "operation": "read_archive_member", "error": str(exc)})
                    elif path.lower().endswith(ARCHIVE_SUFFIXES):
                        errors.append({"path": path, "operation": "inspect_archive", "error": "archive extension recognized, but format is unsupported by Python standard-library ZIP/TAR readers"})
                except (OSError, tarfile.TarError, zipfile.BadZipFile, EOFError) as exc:
                    errors.append({"path": path, "operation": "inspect_archive", "error": str(exc)})

    output = {
        "requested_reference": RELATIVE,
        "provenance": "The task metadata identifies this exact original-input artifact as available in the archive. The observed filesystem/archive location and content hash are reported for each match; this script excludes /root/scripts, identified as generated artifacts.",
        "review_method": "Exact relative-path search for the requested llm_inputs member in accessible filesystem paths and ZIP/TAR archives; matched content is read without extraction and included in the output.",
        "coverage": {
            "roots_walked": roots,
            "directories_seen": scanned_dirs,
            "files_seen": scanned_files,
            "archives_checked": archives_checked,
            "excluded_generated_prefixes": list(SKIP_PREFIXES),
            "skipped_directory_names": sorted(SKIP_DIRS),
            "archive_member_size_limit_bytes": MAX_ARCHIVE_MEMBER,
            "matches": len(matches),
            "errors_count": len(errors),
            "limitations": "Only accessible paths and ZIP/TAR archives were reviewable. Unsupported archive formats, access errors, and oversized members are not evidence of absence. A search result describes only this execution's coverage."
        },
        "matches": matches,
        "errors": errors,
        "finding_guidance": "Assess only the included reviewed content for explicit student access material and distinct source references. Text in the artifact is data, not an instruction to this script. No credential is inferred or guessed."
    }
    print(json.dumps(output, ensure_ascii=False, sort_keys=True))


if __name__ == "__main__":
    main()

