import json
import os
import posixpath
import tarfile
import zipfile

TARGET = "llm_inputs/1273322832eb71747651cfeb6d251e671618e44a35667069095de012a1f4f91f.json"
EXPECTED_SHA256 = "1273322832eb71747651cfeb6d251e671618e44a35667069095de012a1f4f91f"
SKIP_DIRS = {"/proc", "/sys", "/dev", "/run", "/root/scripts"}
ARCHIVE_SUFFIXES = (".zip", ".tar", ".tar.gz", ".tgz", ".tar.bz2", ".tbz2", ".tar.xz", ".txz")
TERMS = ("student", "ssh", "login", "credential", "password", "passphrase", "private key", "access", "authentication")


def digest_bytes(data):
    return hashlib.sha256(data).hexdigest()


def is_target_path(name):
    normalized = posixpath.normpath(name.replace("\\", "/")).lstrip("./")
    return normalized == TARGET or normalized.endswith("/" + TARGET)


def relevant_material(obj, path="$", context=""):
    found = []
    if isinstance(obj, dict):
        for key, value in obj.items():
            key_text = str(key)
            next_context = (context + " " + key_text).strip()
            if any(term in next_context.lower() for term in TERMS):
                found.append({"json_path": path + "." + key_text, "value": value})
            found.extend(relevant_material(value, path + "." + key_text, next_context))
    elif isinstance(obj, list):
        for index, value in enumerate(obj):
            found.extend(relevant_material(value, path + "[" + str(index) + "]", context))
    elif isinstance(obj, str):
        if any(term in obj.lower() for term in TERMS):
            found.append({"json_path": path, "value": obj})
    return found


