errors = []
coverage = {"directories_visited": 0, "files_seen": 0, "archives_examined": 0, "archive_members_examined": 0, "skipped_directories": [], "error_count": 0}


def record_error(where, exc):
    coverage["error_count"] += 1
    if len(errors) < 100:
        errors.append({"path": where, "error": str(exc)})


def examine_archive(path):
    lower = path.lower()
    if not lower.endswith(ARCHIVE_SUFFIXES) and not zipfile.is_zipfile(path):
        return
    coverage["archives_examined"] += 1
    try:
        if zipfile.is_zipfile(path):
            with zipfile.ZipFile(path) as archive:
                for info in archive.infolist():
                    if info.is_dir():
                        continue
                    coverage["archive_members_examined"] += 1
                    if is_target_path(info.filename):
                        try:
                            with archive.open(info) as stream:
                                data = stream.read()
                            candidates.append({"source_type": "archive_member", "source_path": path, "member_path": info.filename, "data": data})
                        except Exception as exc:
                            record_error(path + "!" + info.filename, exc)
            return
        if tarfile.is_tarfile(path):
            with tarfile.open(path, mode="r:*") as archive:
                for member in archive:
                    if not member.isfile():
                        continue
                    coverage["archive_members_examined"] += 1
                    if is_target_path(member.name):
                        try:
                            stream = archive.extractfile(member)
                            if stream is None:
                                raise OSError("archive member has no readable data stream")
                            with stream:
                                data = stream.read()
                            candidates.append({"source_type": "archive_member", "source_path": path, "member_path": member.name, "data": data})
                        except Exception as exc:
                            record_error(path + "!" + member.name, exc)
    except Exception as exc:
        record_error(path, exc)


def on_walk_error(exc):
    record_error(getattr(exc, "filename", "filesystem traversal"), exc)

for walk_root, dirs, files in os.walk("/", topdown=True, onerror=on_walk_error, followlinks=False):
    normalized_root = os.path.normpath(walk_root)
    dirs[:] = [d for d in dirs if os.path.normpath(os.path.join(normalized_root, d)) not in SKIP_DIRS]
    for skipped in SKIP_DIRS:
        if normalized_root == os.path.dirname(skipped) and os.path.basename(skipped) in dirs:
            coverage["skipped_directories"].append(skipped)
    coverage["directories_visited"] += 1
    for filename in files:
        path = os.path.join(walk_root, filename)
        coverage["files_seen"] += 1
        if filename == os.path.basename(TARGET):
            try:
                with open(path, "rb") as stream:
                    candidates.append({"source_type": "filesystem_file", "source_path": path, "member_path": None, "data": stream.read()})
            except Exception as exc:
                record_error(path, exc)
        try:
            examine_archive(path)
        except Exception as exc:
            record_error(path, exc)

reviewed = []
for item in candidates:
    data = item.pop("data")
    actual_hash = digest_bytes(data)
    record = dict(item)
