import hashlib
import json
import os
import stat

REFERENCES = {
    "parent_objective_reference": "c9cdadc469aa426a384f2cf6e9f151fc2b87ec3186812c1c71eade0bb23e5dcc.json",
    "task_spec_metadata_reference": "9d6f04159de43e055e6d51b24f725fe6445a5f5c8b825ea9bbbdd4f89421b5c0.json",
    "supplied_original_input_artifact": "35dba20806a04eb47be359811e41269523064e38f37ec5478408bb286ac2c079.json",
}
SKIP_DIRS = {"/proc", "/sys", "/dev", "/run"}
META_WORDS = ("manifest", "archive", "metadata", "index", "catalog")
found = {name: [] for name in REFERENCES.values()}
llm_inputs_dirs = []
walk_errors = []
walked_dirs = 0


def onerror(exc):
    walk_errors.append({"path": getattr(exc, "filename", None), "error": str(exc)})


def inspect_json_file(path):
    result = {"path": path}
    try:
        with open(path, "rb") as f:
            raw = f.read()
        result["readable"] = True
        result["size_bytes"] = len(raw)
        result["sha256"] = hashlib.sha256(raw).hexdigest()
        try:
            value = json.loads(raw)
            result["json_parse"] = "valid"
            result["top_level_type"] = type(value).__name__
            if isinstance(value, dict):
                result["top_level_keys"] = sorted(str(k) for k in value.keys())
            elif isinstance(value, list):
                result["item_count"] = len(value)
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            result["json_parse"] = "failed"
            result["parse_error"] = str(exc)
    except OSError as exc:
        result.update({"readable": False, "access_error": str(exc)})
    return result


for root, dirs, files in os.walk("/", topdown=True, followlinks=False, onerror=onerror):
    walked_dirs += 1
    dirs[:] = [d for d in dirs if os.path.join(root, d) not in SKIP_DIRS]
    if os.path.basename(root) == "llm_inputs":
        llm_inputs_dirs.append(root)
    for name in REFERENCES.values():
        if name in files:
            found[name].append(os.path.join(root, name))

artifacts = {}
for label, basename in REFERENCES.items():
    paths = []
    for path in sorted(set(found[basename])):
        item = inspect_json_file(path)
        try:
            st = os.stat(path, follow_symlinks=False)
            item["file_type"] = "regular_file" if stat.S_ISREG(st.st_mode) else "other"
            item["mode"] = oct(stat.S_IMODE(st.st_mode))
        except OSError as exc:
            item["stat_error"] = str(exc)
        paths.append(item)
    artifacts[label] = {"supplied_reference": basename, "matches": paths}

nearby_metadata = []
seen_meta = set()
for artifact_info in artifacts.values():
    for match in artifact_info["matches"]:
        parent = os.path.dirname(match["path"])
        try:
            names = os.listdir(parent)
        except OSError as exc:
            nearby_metadata.append({"directory": parent, "access_error": str(exc)})
            continue
        for name in sorted(names):
            low = name.lower()
            if not name.lower().endswith((".json", ".jsonl", ".yaml", ".yml", ".toml")):
                continue
            if name in REFERENCES.values() or not any(word in low for word in META_WORDS):
                continue
            path = os.path.join(parent, name)
            if path in seen_meta:
                continue
            seen_meta.add(path)
            nearby_metadata.append(inspect_json_file(path) if name.lower().endswith(".json") else {"path": path, "present": True, "content_inspected": False})

# Report exact llm_inputs directories encountered, without treating their presence as proof
# that an absent requested file is unavailable elsewhere.
result = {
    "purpose": "Locate the exact supplied archive references and relevant nearby metadata; no network action performed.",
    "references_are_task_supplied": REFERENCES,
    "archive_filesystem_search": {
        "root": "/",
        "excluded_virtual_directories": sorted(SKIP_DIRS),
        "symlinks_followed": False,
        "directories_walked": walked_dirs,
        "llm_inputs_directories_found": sorted(set(llm_inputs_dirs)),
        "access_errors_count": len(walk_errors),
        "access_errors": walk_errors,
    },
    "artifacts": artifacts,
    "nearby_archive_metadata": nearby_metadata,
    "coverage_note": "Only exact basenames were searched across directories reachable during this walk. Virtual filesystems were excluded, symlinks were not followed, and permission or traversal errors limit coverage. Nearby metadata inspection was limited to files with archive/index/manifest/metadata/catalog names in the matched artifact directories. A filesystem match establishes accessibility at that path, not provenance or archive authenticity.",
}
print(json.dumps(result, ensure_ascii=False, sort_keys=True))

