import hashlib
import json
import os
import re
import tarfile
import zipfile
from pathlib import PurePosixPath

REL = "llm_inputs/78f03b25cad5bff5e1b7587eb6846fe71820c3db673f2544a94d3f28d782a621.json"
BASENAME = PurePosixPath(REL).name
EXCLUDED = {"/proc", "/sys", "/dev", "/run", "/root/scripts"}
ARCHIVE_SUFFIXES = (".zip", ".tar", ".tar.gz", ".tgz", ".tar.bz2", ".tbz2", ".tar.xz", ".txz")


def normalized_member(name):
    return name.replace("\\", "/").lstrip("./")


def add_observation(found, source, data, kind):
    if not data:
        return
    key = (source, hashlib.sha256(data).hexdigest())
    if key not in {(x["source"], x["sha256"]) for x in found}:
        found.append({"source": source, "kind": kind, "data": data})


def read_archive_member(path):
    try:
        if path.lower().endswith(".zip") and zipfile.is_zipfile(path):
            with zipfile.ZipFile(path) as zf:
                for info in zf.infolist():
                    if normalized_member(info.filename) == REL:
                        with zf.open(info, "r") as stream:
                            return stream.read(), None
        elif path.lower().endswith(ARCHIVE_SUFFIXES):
            with tarfile.open(path, "r:*") as tf:
                for member in tf.getmembers():
                    if member.isfile() and normalized_member(member.name) == REL:
                        stream = tf.extractfile(member)
                        if stream is None:
                            return None, "archive member could not be read"
                        with stream:
                            return stream.read(), None
    except Exception as exc:
        return None, "%s: %s" % (type(exc).__name__, str(exc))
    return None, None


def collect_strings(value, path="$", key=""):
    out = []
    if isinstance(value, dict):
        for k, v in value.items():
            out.extend(collect_strings(v, path + "." + str(k), str(k)))
    elif isinstance(value, list):
        for i, v in enumerate(value):
            out.extend(collect_strings(v, "%s[%d]" % (path, i), key))
    elif isinstance(value, str):
        out.append({"json_path": path, "key": key, "value": value})
    return out


def assess(data):
    result = {"byte_count": len(data), "sha256": hashlib.sha256(data).hexdigest()}
    try:
        text = data.decode("utf-8")
        result["decoding"] = "utf-8"
        result["full_text"] = text
    except UnicodeDecodeError as exc:
        text = data.decode("utf-8", errors="replace")
        result["decoding"] = "utf-8 with replacement; original bytes are not fully represented in text"
        result["decode_error"] = str(exc)
        result["full_text"] = text

    try:
        document = json.loads(text)
        result["json_parse"] = "success"
        strings = collect_strings(document)
        refs = []
        potential_access = []
        for item in strings:
            value = item["value"]
            key = item["key"].lower()
            # Record explicit path-like references and strings in source/reference fields.
            if (re.search(r"(?:^|[\\s'\"])(?:[A-Za-z0-9_.-]+/)+[A-Za-z0-9_.-]+", value)
                    or any(word in key for word in ("source", "reference", "input", "file", "path"))):
                refs.append(item)
            # These are review leads, not automatic proof of authorization or usability.
            if re.search(r"\b(?:ssh|student|password|passwd|credential|private[ _-]?key|authorized_keys|login)", value, re.I):
                potential_access.append(item)
        result["task_source_reference_candidates"] = refs
        result["access_material_review_candidates"] = potential_access
        result["access_material_assessment"] = "Candidates are reported for review; presence of these words alone does not establish authorized or usable SSH material."
    except Exception as exc:
        result["json_parse"] = "failed"
        result["json_parse_error"] = "%s: %s" % (type(exc).__name__, str(exc))
        result["task_source_reference_candidates"] = []
        result["access_material_review_candidates"] = []
    return result


def main():
    found = []
    errors = []
    visited_dirs = 0
    visited_files = 0
    archive_candidates = 0
    roots = ["/"]
    cwd = os.path.abspath(os.getcwd())
    if cwd != "/":
        roots.insert(0, cwd)

    seen_dirs = set()
    for root in roots:
        for current, dirs, files in os.walk(root, topdown=True, followlinks=False):
            current = os.path.abspath(current)
            if current in seen_dirs:
                dirs[:] = []
                continue
            seen_dirs.add(current)
            visited_dirs += 1
            kept = []
            for name in dirs:
                candidate = os.path.abspath(os.path.join(current, name))
                if candidate in EXCLUDED or any(candidate.startswith(x + os.sep) for x in EXCLUDED):
                    continue
                kept.append(name)
            dirs[:] = kept

            # Test only the exact requested relative path in each traversed directory.
            if os.path.basename(current) == "llm_inputs":
                exact = os.path.join(current, BASENAME)
                try:
                    if os.path.isfile(exact):
                        with open(exact, "rb") as stream:
                            add_observation(found, exact, stream.read(), "filesystem file")
                except OSError as exc:
                    errors.append({"path": exact, "error": str(exc)})

            for name in files:
                path = os.path.join(current, name)
                visited_files += 1
                if name.lower().endswith(ARCHIVE_SUFFIXES):
                    archive_candidates += 1
                    data, error = read_archive_member(path)
                    if data is not None:
                        add_observation(found, path + "!" + REL, data, "archive member")
                    if error:
                        errors.append({"path": path, "error": error})

    observations = []
    for item in found:
        report = {"source": item["source"], "kind": item["kind"]}
        report.update(assess(item["data"]))
        observations.append(report)

    output = {
        "requested_relative_path": REL,
        "search": {
            "roots": roots,
            "excluded_paths": sorted(EXCLUDED),
            "directories_visited": visited_dirs,
            "files_seen": visited_files,
            "archive_candidates_checked": archive_candidates,
            "access_or_archive_errors_count": len(errors),
            "access_or_archive_errors_examples": errors[:30],
            "coverage_note": "Searched traversable filesystem directories for the exact relative path and common ZIP/TAR archive suffixes. Symlinked directories, excluded paths, inaccessible locations, and other archive formats were not covered."
        },
        "found_count": len(observations),
        "artifacts": observations,
        "conclusion_limit": "No finding means only that this search did not locate the exact path within reported coverage; it does not establish that the artifact is absent from other storage or archive formats."
    }
    print(json.dumps(output, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

